pub(super) fn ensure_available(
    start: usize,
    len: usize,
    track_end: usize,
    context: &str,
) -> Result<(), String> {
    let end = start
        .checked_add(len)
        .ok_or_else(|| format!("{context} length overflow"))?;
    if end > track_end {
        return Err(format!(
            "Truncated {context}: need bytes [{}..{}), track ends at {}",
            start, end, track_end
        ));
    }
    Ok(())
}

